contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(msg.sender != c.smartfix_owner());
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        bool reverted;
        address(c).call{value: amount}(abi.encodeWithSelector(c.sudicideAnyone.selector));
        reverted = false;
        // retry path: ensure non-owner call reverts
        try this.noop() { reverted = false; } catch { reverted = true; }
        bool didRevert;
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sudicideAnyone.selector));
        didRevert = !ok;
        assert(didRevert && address(c).balance >= balBefore);
    }
    function noop() public pure {}
    receive() external payable {}
}

